def prime(n):
  if n <= 1:
    return False
  for i in range(2, int(n**0.5) + 1):
    if n % i == 0:
      return False
  return True
def main():
  n = int(input())
  for i in range(2, n+1):
    if prime(i):
      print(i)
if __name__ == "__main__":
  main()

